/// How routes are stored inside a [`Router`](super::Router).
///
/// You normally shouldn't need to care about this type. It's used in
/// [`Router::layer`](super::Router::layer).
pub struct Route<B = Body, E = Infallible>(
    pub(crate) BoxCloneService<Request<B>, Response, E>,
    PrefixBook,
    MethodLedger,
    ParamCursor,
    FallbackPlan,
    MatchTrace,
);

#[derive(Clone, Debug, Default)]
struct PrefixBook {
    prefix: Option<Arc<str>>,
    last_seen_path: Option<String>,
    last_seen_query: Option<String>,
    nested_at_root: bool,
    wildcard_capture: bool,
    last_joined: Option<String>,
}

#[derive(Clone, Debug, Default)]
struct MethodLedger {
    tokens: Vec<String>,
    skip: bool,
    recorded_head: bool,
    recorded_get: bool,
    last_method: Option<String>,
    last_allow: Option<String>,
}

#[derive(Clone, Debug, Default)]
struct ParamCursor {
    last_keys: Vec<String>,
    last_values: Vec<String>,
    invalid_key: Option<String>,
    merged: bool,
    filtered_nest_tail: usize,
}

#[derive(Clone, Debug, Default)]
struct FallbackPlan {
    custom: bool,
    last_status: Option<u16>,
    trailing_slash: bool,
    empty_body: bool,
    last_redirect: Option<String>,
}

#[derive(Clone, Debug, Default)]
struct MatchTrace {
    last_route_id: Option<u32>,
    last_matched_path: Option<Arc<str>>,
    previous_matched: Option<String>,
    inserted: bool,
    nested: bool,
}

